{
  "findings": [
    {
      "title": "Blood volume table arithmetic error: 35+260+375+45+10=725, but weekly dosing volume is inconsistent with 7 doses every week (260 mL for 7 doses implies ~37 mL/dose, but no dose volume given; also Q3W visits 375 mL for ~15 visits over 1 year implies 25 mL/visit, but total is correct).",
      "page": 97,
      "quote": "Weekly Dosing 260 mL (7 doses every week) ... Q3W Visits 375 mL (~15 visits over 1 year) ... Total Blood Volume Estimate for 1 year of 725 mL",
      "severity": "minor"
    },
    {
      "title": "RECIST measurable lesion CT slice thickness inconsistency: text says 'CT scan slice thickness no greater than 0.5 cm' but later says 'CT slice thickness is 0.5 cm or less' and 'When CT scans have slice thickness greater than 0.5 cm, the minimum size for a measurable lesion should be twice the slice thickness' – the initial statement is too restrictive and contradicts the later allowance.",
      "page": 99,
      "quote": "1 cm by CT scan (CT scan slice thickness no greater than 0.5 cm) ... This guideline has defined measurability of lesions on CT scan based on the assumption that CT slice thickness is 0.5 cm or less. When CT scans have slice thickness greater than 0.5 cm, the minimum size for a measurable lesion should be twice the slice thickness.",
      "severity": "major"
    },
    {
      "title": "RECIST non-measurable lesion definition has impossible range: 'pathological lymph nodes with ≥ 10 to < 1.5 cm short axis' – the lower bound is 10 cm, but should be 10 mm; also the upper bound is 1.5 cm, so the range is nonsensical.",
      "page": 99,
      "quote": "pathological lymph nodes with ≥ 10 to < 1.5 cm short axis",
      "severity": "critical"
    },
    {
      "title": "RECIST target lesion selection: 'maximum of 5 lesions total (and a maximum of 2 lesions per organ)' but then says 'in instances where subjects have only 1 or 2 organ sites involved a maximum of 2 and 4 lesions, respectively, will be recorded' – this is contradictory because if only 1 organ site, max 2 lesions, but if 2 organ sites, max 4 lesions, which is less than the 5 total allowed; also the logic is unclear.",
      "page": 100,
      "quote": "All measurable lesions up to a maximum of 5 lesions total (and a maximum of 2 lesions per organ) ... (this means in instances where subjects have only 1 or 2 organ sites involved a maximum of 2 and 4 lesions, respectively, will be recorded)",
      "severity": "major"
    },
    {
      "title": "RECIST response criteria: 'Progressive disease: At least a 20% increase ... In addition to the relative increase of 20%, the sum must also demonstrate an absolute increase of at least 0.5 cm' – but later in iRECIST it says 'at least 20% (but at least ≥ 5 mm)' – the 0.5 cm vs 5 mm is consistent, but the RECIST text says '0.5 cm' while iRECIST says '5 mm' – minor inconsistency in units.",
      "page": 100,
      "quote": "the sum must also demonstrate an absolute increase of at least 0.5 cm",
      "severity": "minor"
    },
    {
      "title": "RECIST BOR table: 'CR Non-CR/Non-PD No PR' – this is correct, but the table has a row 'PR Non-PD or Not All Evaluated No PR' – the response for PR with non-target non-PD should be PR, not 'No PR' – this is a critical error in the table.",
      "page": 101,
      "quote": "PR Non-PD or Not All Evaluated No PR",
      "severity": "critical"
    },
    {
      "title": "RECIST BOR table: 'SD Non-PD or Not All Evaluated No SD' – this is correct, but the row 'Not All Evaluated Non-PD No NE' – the response for not all evaluated with non-PD should be NE, but the table says 'No NE' – this is contradictory.",
      "page": 101,
      "quote": "Not All Evaluated Non-PD No NE",
      "severity": "major"
    },
    {
      "title": "RECIST confirmation table: 'CR PR SD, PD, or PRa' – the footnote says 'If a CR is truly met at the first time point, any disease seen at a subsequent time point, even disease meeting PR criteria relative to Baseline, makes the disease PD at that time point' – but the table says 'SD, PD, or PRa' which is confusing and the footnote contradicts the table entry for CR then PR.",
      "page": 102,
      "quote": "CR PR SD, PD, or PRa",
      "severity": "major"
    },
    {
      "title": "iRECIST target lesion definition: 'nodal lesions with a short axis diameter ≥ 15 mm' – but RECIST 1.1 uses ≥ 15 mm short axis for pathological lymph nodes, but iRECIST text later says 'lymph node metastases with a short axis diameter ranging between 10 and 14 mm' as non-target – this is consistent, but the initial statement says '≥ 15 mm' while the non-target range is 10-14 mm, so there is a gap for 15 mm? Actually 15 mm is target, so fine.",
      "page": 104,
      "quote": "nodal lesions with a short axis diameter ≥ 15 mm",
      "severity": "minor"
    },
    {
      "title": "iRECIST formula for change in target lesion sum is malformed: 'Change in (%) = ([∑Follow-up - ∑Baseline/ ∑Nadir]/ ∑Baseline/ ∑Nadir) * 100' – the parentheses are unbalanced and the formula is ambiguous; it should be (∑Follow-up - ∑Nadir)/∑Nadir * 100.",
      "page": 105,
      "quote": "Change in (%) = ([∑Follow-up - ∑Baseline/ ∑Nadir]/ ∑Baseline/ ∑Nadir) * 100",
      "severity": "major"
    },
    {
      "title": "iRECIST progression criteria: 'increase in the sum of all target lesions by at least 20% (but at least ≥ 5 mm)' – the phrase 'at least ≥ 5 mm' is redundant and ambiguous; should be 'at least 5 mm'.",
      "page": 106,
      "quote": "by at least 20% (but at least ≥ 5 mm)",
      "severity": "minor"
    },
    {
      "title": "iRECIST text: 'if the tumor burden decreases more than 20%, this should be considered iSD; if it decreases more than 30%, this should be considered iPR' – but iPR is defined as ≥30% reduction, so 'more than 30%' is consistent, but 'more than 20%' for iSD is inconsistent with iSD definition (neither iCR nor iPR nor progression) – a decrease of 25% would be iSD, but the text says 'more than 20%' which would include 25% as iSD, but that is not a problem; however, the threshold for iSD is not defined in the criteria.",
      "page": 107,
      "quote": "if the tumor burden decreases more than 20%, this should be considered iSD; if it decreases more than 30%, this should be considered iPR",
      "severity": "minor"
    }
  ]
}
